SELECT "@timestamp_date" AS "@timestamp_date", "APPLICATION" AS "APPLICATION", "STATUS_INFO" AS "STATUS_INFO", "JOB_DURATION_d" AS "JOB_DURATION_d", "ERROR_DESCRIPTION" AS "ERROR_DESCRIPTION" 
FROM "default"."jobs" 
WHERE "@timestamp_date" >= TIMESTAMP '2026-03-25 00:00:00.000000' AND "@timestamp_date" < TIMESTAMP '2026-04-02 00:00:00.000000' AND "STATUS_INFO" = 'FAILED' GROUP BY "@timestamp_date", "APPLICATION", "STATUS_INFO", "JOB_DURATION_d", "ERROR_DESCRIPTION" ORDER BY "@timestamp_date" DESC 
 LIMIT 1000;